#!/usr/bin/env python3

import subprocess
import sys

# Import functions from user_config.py
from user_config import get_usernames, get_passwords, get_sudo_config

def create_user(username):
    """Create a user with useradd command"""
    try:
        subprocess.run(['useradd', '-m', username], check=True)
        print(f"User {username} created successfully")
    except subprocess.CalledProcessError as e:
        print(f"Failed to create user {username}: {e}")

def set_password(username, password):
    """Set password for a user with chpasswd command"""
    try:
        process = subprocess.Popen(['chpasswd'], stdin=subprocess.PIPE, text=True)
        process.communicate(input=f"{username}:{password}")
        if process.returncode == 0:
            print(f"Password set for user {username}")
        else:
            print(f"Failed to set password for user {username}")
    except Exception as e:
        print(f"Error setting password for user {username}: {e}")

def add_sudo_config(sudo_config):
    """Append sudo configuration to /etc/sudoers"""
    try:
        with open('/etc/sudoers', 'a') as sudoers_file:
            sudoers_file.write(sudo_config + '\n')
        print("Sudo configuration added successfully")
    except Exception as e:
        print(f"Failed to add sudo configuration: {e}")

def main():
    # Get usernames and passwords
    usernames = get_usernames()
    passwords = get_passwords()
    sudo_config = get_sudo_config()

    # Create users and set passwords
    for username in usernames:
        create_user(username)
        if username in passwords:
            set_password(username, passwords[username])

    # Add sudo configuration
    add_sudo_config(sudo_config)

if __name__ == "__main__":
    main()
